window.__anim=(function(){
  var G=Arena.Game, W=G.world, Met=Arena.Sim.ArenaMetrics, CB=Arena.Render.CharacterBackend;
  /* El bucle rAF simula entre sonda y sonda. Se congela y cada sonda avanza
     mundo, personajes Y partículas, que es lo que hace el bucle real. */
  G._running=false;
  function foe(p){for(var i=0;i<W.entities.length;i++){var e=W.entities[i];if(e.team!==p.team&&e.alive)return e;}return null;}
  window.__intent=function(e){var h=G.renderer.characterHandleOf(e.id);return h?CB.current.intentOf(h):null;};
  /* `pose` se rellena en render(), no en syncVisuals(): medir sin pintar daba
     cero piezas y la comprobación de pose era vacía. */
  window.__nPaso=0;
  window.__paso=function(){W.stepSeconds(1/60);G.renderer.syncVisuals(1/60);if(Arena.Render.VFX)Arena.Render.VFX.update(1/60);
    /* Pintar por software cuesta: basta con hacerlo cada pocos pasos para que
       `pose` esté al día, y una vez más justo antes de medirla. */
    if((window.__nPaso++%6)===0)G.renderer.render(1,1/60);};
  window.__pinta=function(){G.renderer.render(1,1/60);};
  window.__adv=function(sec){var n=Math.round(sec*60);for(var i=0;i<n;i++)window.__paso();};
  window.__vfxVivas=function(){var v=Arena.Render.VFX;if(!v||!v.particles)return -1;var n=0;for(var i=0;i<v.particles.length;i++)if(v.particles[i].alive)n++;return n;};
  /* Recorre TODO número de la pieza, sin suponer nombres de campo. */
  window.__poseSano=function(e){
    var v=G.renderer.visuals[e.id];
    if(!v||!v.pose)return {ok:false,piezas:0,why:'sin pose'};
    var malos=0,extremos=0,leidos=0;
    function mira(x,prof){
      if(prof>2||x==null)return;
      if(typeof x==='number'){leidos++;if(!isFinite(x))malos++;else if(Math.abs(x)>200)extremos++;return;}
      if(typeof x!=='object')return;
      for(var k in x)mira(x[k],prof+1);
    }
    for(var i=0;i<v.pose.length;i++)mira(v.pose[i],0);
    return {ok:malos===0&&extremos===0,piezas:v.pose.length,numeros:leidos,noFinitos:malos,fueraDeRango:extremos};
  };
  window.__setupAnim=function(classId,libre){
    W.settings.aiEnabled=false;
    G.setPlayerClass(classId);
    var p=W.getPlayer(), t=foe(p);
    t.aiEnabled=false; t.hpMax=200000; t.hp=200000;
    p.hp=p.hpMax; p.resource=p.resourceMax; p.gcdUntil=0; p.cooldowns=Object.create(null);
    p.schoolLockouts=Object.create(null);
    Arena.Combat.AbilitySystem.cancelCast(W,p,'sweep'); p.pendingCast=null; p.queuedAction=null; p.queued=null;
    var St=Arena.Combat.StatusSystem;
    while(p.statuses.length)St.removeInstance(W,p,p.statuses[0],'sweep');
    while(t.statuses.length)St.removeInstance(W,t,t.statuses[0],'sweep');
    if(libre){
      /* Sitio despejado: pegado al enemigo, avanzar choca y la locomoción da
         IDLE. Eso mediría la colisión, no la animación. */
      p.pos.x=0;p.pos.z=0;p.prevPos.x=0;p.prevPos.z=0;p.yaw=0;p.prevYaw=0;
      t.pos.x=0;t.pos.z=14;t.prevPos.x=0;t.prevPos.z=14;
    } else {
      for(var d=0;d<360;d+=7){var a=d*Math.PI/180;var x=t.pos.x+Math.cos(a)*2.4,z=t.pos.z+Math.sin(a)*2.4;if(!Met.walkable(W.arena,x,z,0.6))continue;p.pos.x=x;p.pos.z=z;p.prevPos.x=x;p.prevPos.z=z;p.yaw=Math.atan2(t.pos.x-x,t.pos.z-z);p.prevYaw=p.yaw;break;}
    }
    p.targetId=t.id;
    G.renderer.syncVisuals(1/60);
    return {p:p,t:t};
  };
  return 'listo';
})()
